using Stock.Core;
using Stock.Core.Research;
using Stock.Core.Research.Oversold;
using Stock.Core.Trading;

internal static partial class Program
{
    private static readonly StockItem DailyStock=new("005930","검사 종목",Exchange.KRX,"005930","검사");
    private static DateTimeOffset DailyTime(int day,int hour=15,int minute=30)=>new DateTimeOffset(2025,1,1,hour,minute,0,TimeSpan.FromHours(9)).AddDays(day);
    private static PriceBar DailyBar(int day,decimal close,decimal? open=null,decimal? high=null,decimal? low=null,decimal volume=100)=>new(DailyTime(day),open??close,high??Math.Max(open??close,close),low??Math.Min(open??close,close),close,volume);
    private static HistoricalFacts DailyFacts(int count)=>new(){Source="TEST_FIXTURE · synthetic session calendar",MarketSessions=Enumerable.Range(0,count).Select(i=>new DailyMarketSession(DateOnly.FromDateTime(DailyTime(i).DateTime),DailyTime(i,9,0),DailyTime(i))).ToArray(),StatusRecords=Enumerable.Range(0,count).Select(i=>new DailySecurityStatus("005930",DateOnly.FromDateTime(DailyTime(i).DateTime),DailyTime(i,8,0),HistoricalBoard.Kospi,HistoricalSecurityKind.Common,false,false)).ToArray(),TradingValues=Enumerable.Range(0,count).Select(i=>new DailyTradingValue("005930",DateOnly.FromDateTime(DailyTime(i).DateTime),DailyTime(i),4_000_000_000)).ToArray(),RiskRecords=Enumerable.Range(0,count).Select(i=>new FundamentalRiskRecord("005930",DateOnly.FromDateTime(DailyTime(i).DateTime),false,DailyTime(i,8,0))).ToArray()};
    private sealed class FixedDailySupport(Func<int,decimal>? center=null):ISupportProvider
    {
        public IReadOnlyList<SupportCandidate> Get(IReadOnlyList<PriceBar> h,OversoldConfig c){if(h.Count==0)return [];var p=center?.Invoke(h.Count)??80;var d=DailyDates.Of(h[^1]);return [new("A",SupportKind.MovingAverage,p-10,p,p+10,d,d,"fixture"),new("B",SupportKind.ConfirmedPivotHigh,p-10,p,p+10,d,d,"fixture")];}
    }
    private static OversoldConfig DailyConfig()=>new(){AverageTradingValueLookbackDays=2,CrashLookbackDays=3,ShortCrashLookbackDays=3,UseRsiFilter=false,UseVolumeFilter=false,UseTakeProfit1=false,UseTakeProfit2=false,UseTrailingStop=false,UseEmergencyStop=false,CommissionPercent=0,InitialCapital=10_000,PlannedInvestment=8_000,MaxHoldingDays=100,MovingAveragePeriods="1,2"};
    private static OversoldResult DailyRun(PriceBar[] bars,OversoldConfig? cfg=null,HistoricalFacts? facts=null,int start=2,ISupportProvider? support=null)=>new OversoldBacktest().Run(new(DailyStock,bars,"TEST_FIXTURE",DailyTime(100)),cfg??DailyConfig(),DateOnly.FromDateTime(DailyTime(start).DateTime),DailyDates.Of(bars[^1]),facts??DailyFacts(bars.Length),supportProviders:[support??new FixedDailySupport()]);
    private static void OversoldTests()
    {
        new OversoldConfig().Validate();Check(true,"oversold defaults validate");
        var cfg=DailyConfig();cfg.EntryRatios="40,30,20";Throws<InvalidOperationException>(cfg.Validate,"entry allocation sum validated");cfg=DailyConfig();cfg.UseTakeProfit1=cfg.UseTakeProfit2=true;cfg.TakeProfit2Percent=5;Throws<InvalidOperationException>(cfg.Validate,"profit targets cross validation");
        cfg=DailyConfig();var cache=new OversoldIndicatorCache(cfg);cache.Append(DailyBar(0,100));cache.Append(DailyBar(1,100));var indicator=cache.Append(DailyBar(2,80,high:110));Check(indicator.Trigger=="Medium+Short"&&Math.Abs(indicator.ShortDrawdown-(-3000m/110))<.00001m,"crash uses current included HIGH not prior CLOSE");
        cfg.RsiPeriod=2;cache=new(cfg);cache.Append(DailyBar(0,10));cache.Append(DailyBar(1,12));Check(cache.Append(DailyBar(2,11)).Rsi is {} rsi&&Math.Abs(rsi-66.666666m)<.00001m,"Wilder RSI seed");Check(Math.Abs(cache.Append(DailyBar(3,10)).Rsi!.Value-40)<.00001m,"Wilder RSI subsequent smoothing");
        cfg.VolumeLookbackDays=2;cache=new(cfg);cache.Append(DailyBar(0,100,volume:100));cache.Append(DailyBar(1,100,volume:100));Check(cache.Append(DailyBar(2,80,volume:200)).VolumeRatio==2,"volume ratio excludes current volume");
        cfg.PivotLeftBars=cfg.PivotRightBars=1;var pivot=new ConfirmedPivotHighProvider();PriceBar[] ph=[DailyBar(0,80),DailyBar(1,100),DailyBar(2,80),DailyBar(3,90),DailyBar(4,80)];Check(pivot.Get(ph.Take(2).ToArray(),cfg).Count==0,"pivot unavailable before right confirmation");var ps=pivot.Get(ph,cfg);Check(ps.Count==2&&ps[0].Occurred==DailyDates.Of(ph[1])&&ps[0].Confirmed==DailyDates.Of(ph[2]),"all confirmed pivots retained with separate dates");
        Check(new ConfirmedPivotHighProvider().Get([DailyBar(0,100),DailyBar(1,100),DailyBar(2,90)],cfg).Count==0,"equal high is not strict pivot");
        cfg.MovingAveragePeriods="2,999";Check(new MovingAverageSupportProvider().Get(ph,cfg).Count==1,"unprepared MA999 individually excluded");
        var approx=new ApproximateVolumeZoneProvider();cfg.VolumeZoneBinSize=1;cfg.VolumeZoneLookbackDays=5;cfg.VolumeZoneMaxBins=10;var bins=approx.Allocate([DailyBar(0,100,high:110,low:10,volume:101),DailyBar(1,100,volume:7)],cfg);Check(bins.Sum(b=>b.Volume)==108&&bins.Count<=10,"approximate bins conserve volume and bound count");Check(approx.Allocate([DailyBar(0,100,volume:7)],cfg).Single().Volume==7,"flat daily range assigned once");
        SupportCandidate Candidate(string id,decimal p)=>new(id,SupportKind.MovingAverage,p,p,p,new(2025,1,1),new(2025,1,1),"fixture");var clusters=SupportClustering.Build([Candidate("A",100),Candidate("B",105),Candidate("C",110),Candidate("A",100)],5);Check(clusters.Length==1&&clusters[0].Count==3&&clusters[0].Upper-clusters[0].Lower==10,"transitive adjacent cluster and duplicate IDs");Check(clusters[0].Approached(97,3)&&!clusters[0].Approached(96.9m,3),"cluster expanded boundary inclusive");
        PriceBar[] basic=[DailyBar(0,100),DailyBar(1,100),DailyBar(2,80),DailyBar(3,80,open:82),DailyBar(4,80)];var run=DailyRun(basic);var fill=run.Trades.Single().Executions.Single();Check(fill.SignalTime==DailyTime(2)&&fill.ExecutionTime==DailyTime(3,9,0)&&fill.Price==82,"closed signal fills following opening gap");Check(fill.Quantity==39&&run.Cash==6802,"integer budget applies actual opening price");Check(run.Trades.Count==1&&run.Performance.Trades==0&&run.Performance.OpenTrades==1,"unclosed trade excluded from completed statistics");
        var prefix=DailyRun(basic.Take(3).ToArray());Check(prefix.Trades.Count==0&&prefix.PendingOrderAtEnd,"last signal remains pending without synthetic final fill");Check(Serialization.Pack(prefix.Signals)==Serialization.Pack(run.Signals.Where(s=>s.SignalTime<=DailyTime(2)).ToArray()),"future suffix does not change past signals");
        cfg=DailyConfig();cfg.UseRsiFilter=true;Check(DailyRun(basic,cfg).Trades.Count==0,"unready active RSI blocks entry");cfg=DailyConfig();cfg.UseVolumeFilter=true;Check(DailyRun(basic,cfg).Trades.Count==0,"active volume filter blocks independently");
        var facts=DailyFacts(5);facts.RiskRecords=[];Check(DailyRun(basic,facts:facts).Trades.Count==0,"missing risk is unknown not safe");facts=DailyFacts(5);facts.RiskRecords=facts.RiskRecords.Select(r=>r with{KnownAt=DailyTime(50)}).ToArray();Check(DailyRun(basic,facts:facts).Trades.Count==0,"future risk knowledge not backfilled");facts=DailyFacts(5);facts.TradingValues=[];Check(DailyRun(basic,facts:facts).Trades.Count==0,"OHLCV does not invent actual turnover");
        foreach(var kind in new[]{HistoricalSecurityKind.Etf,HistoricalSecurityKind.Etn,HistoricalSecurityKind.Spac}){facts=DailyFacts(5);facts.StatusRecords=facts.StatusRecords.Select(r=>r with{Kind=kind}).ToArray();Check(DailyRun(basic,facts:facts).Trades.Count==0,"excluded historical kind "+kind);}
        facts=DailyFacts(5);facts.StatusRecords[3]=facts.StatusRecords[3] with{Suspended=true};run=DailyRun(basic,facts:facts);Check(run.Trades.Single().FirstExecutionDate==DailyTime(4,9,0),"halt delays opening execution");facts=DailyFacts(5);facts.RiskRecords[3]=facts.RiskRecords[3] with{IsRisk=true};Check(DailyRun(basic,facts:facts).Trades.Count==0,"next-open risk recheck cancels entry");
        PriceBar[] scale=[DailyBar(0,100),DailyBar(1,100),DailyBar(2,80),DailyBar(3,75,open:80),DailyBar(4,71,open:75),DailyBar(5,71,open:71),DailyBar(6,60),DailyBar(7,58)];run=DailyRun(scale);Check(run.Trades[0].Executions.Count(e=>e.Buy)==3,"three scale entries count only fills");Check(run.Trades[0].Cluster.Lower==70&&run.Trades[0].ExitReason=="SupportBreak"&&run.Trades[0].LastExecutionDate==DailyTime(7,9,0),"first support frozen across scale entries and next-open stop");Check(run.Trades[0].Executions.Where(e=>!e.Buy).Sum(e=>e.RealizedPnl)==run.Trades[0].RealizedPnl&&run.Cash-10000==run.Trades[0].RealizedPnl,"realized ledger equals final cash and history fills");
        cfg=DailyConfig();cfg.UseEmergencyStop=true;cfg.UseTakeProfit1=true;PriceBar[] collision=[..basic.Take(3),DailyBar(3,80,high:100,low:65),DailyBar(4,70)];run=DailyRun(collision,cfg);Check(run.Trades[0].ExitReason=="EmergencyStop"&&!run.Trades[0].Executions.Any(e=>e.Reason=="TP1"),"stop takes priority over same daily profit touch");
        cfg=DailyConfig();cfg.UseTakeProfit1=cfg.UseTakeProfit2=true;PriceBar[] profit=[..basic.Take(3),DailyBar(3,100,open:80),DailyBar(4,100),DailyBar(5,75)];run=DailyRun(profit,cfg);Check(run.Trades[0].Executions.Where(e=>!e.Buy).Select(e=>e.Quantity).SequenceEqual([12,12])&&run.Quantity==16,"two harvests share frozen maximum quantity basis");Check(!run.Signals.Any(s=>s.Action=="Buy"&&s.SignalTime>DailyTime(2)),"no additional entries after actual harvest");
        cfg=DailyConfig();cfg.UseTrailingStop=true;cfg.TrailingActivation=TrailingActivation.AfterEntry;run=DailyRun([..basic.Take(3),DailyBar(3,95,open:80,high:100,low:78),DailyBar(4,94),DailyBar(5,90),DailyBar(6,89)],cfg);Check(!run.Signals.Any(s=>s.Action=="Sell"&&s.SignalTime==DailyTime(3))&&run.Trades[0].ExitReason=="TrailingStop","trailing checks prior peak before today's high");
        cfg=DailyConfig();cfg.MaxHoldingDays=2;run=DailyRun([..basic,DailyBar(5,80)],cfg);Check(run.Trades[0].Executions.Last().SignalTime==DailyTime(4)&&run.Trades[0].LastExecutionDate==DailyTime(5,9,0),"holding includes entry session and exits subsequent open");
        cfg=DailyConfig();cfg.RequireReboundConfirmation=true;run=DailyRun([..basic.Take(3),DailyBar(3,81,high:100,low:79),DailyBar(4,82,low:81),DailyBar(5,82)],cfg);Check(!run.Signals.Any(s=>s.SignalTime==DailyTime(2))&&run.Trades[0].FirstExecutionDate==DailyTime(5,9,0),"rebound tracks low only after confirmed first approach");
        cfg=DailyConfig();cfg.CommissionPercent=1;cfg.TaxPercent=1;cfg.SlippagePercent=1;run=DailyRun(scale,cfg);Check(run.Cash>=0&&run.Trades[0].RealizedPnl==run.Cash-cfg.InitialCapital&&run.Trades[0].Executions.All(e=>e.Fee>0),"fees tax slippage reconcile without negative cash");
        cfg=DailyConfig();cfg.PlannedInvestment=1;run=DailyRun(basic,cfg);Check(run.Trades.Count==0&&run.Cash==10000&&run.Notices.Any(n=>n.Contains("0주")),"zero quantity never counts as an entry");
        facts=DailyFacts(5);facts.MarketSessions=[];run=DailyRun(basic,facts:facts);Check(run.Decisions.Count==3&&run.Trades.Count==1&&run.Notices.Any(n=>n.Contains("완성 일봉")),"actual completed bars derive sessions without inventing weekdays");
        var verificationBars=new[]{DailyBar(0,100),DailyBar(1,100),DailyBar(2,80,high:100),DailyBar(3,90,open:80,high:100,low:79),DailyBar(4,70),DailyBar(5,70)};
        foreach(var preset in Stock.App.StrategyDiagnosticPreset.BacktestVerificationPresets())
        {
            var verified=new OversoldBacktest().Run(new(DailyStock,verificationBars,"TEST_FIXTURE",DailyTime(100)),preset.Value,DailyDates.Of(verificationBars[0]),DailyDates.Of(verificationBars[^1]),new());
            var expected=preset.Key==Stock.App.StrategyDiagnosticPreset.HoldOneDayName?"MaxHoldingDays":preset.Key==Stock.App.StrategyDiagnosticPreset.QuickProfitName?"TP1":"SupportBreak";
            Console.WriteLine($"VERIFY {preset.Key}: decisions={verified.Decisions.Count}, signals={verified.Signals.Count}, trades={verified.Trades.Count}, completed={verified.Performance.Trades}, exits={string.Join(',',verified.Trades.Select(t=>t.ExitReason))}, reasons={string.Join('|',verified.Decisions.Select(d=>d.Reason).Distinct())}");
            Check(verified.Decisions.Count==verificationBars.Length&&verified.Performance.Trades>=1&&verified.Trades.Any(t=>t.ExitReason==expected),preset.Key+" creates the expected completed trade from price-only daily data");
        }
        var win=new OversoldTrade{RealizedPnl=20,FinalReturnPercent=20,HoldingDays=2,LastExecutionDate=DailyTime(1)};var loss=new OversoldTrade{RealizedPnl=-10,FinalReturnPercent=-10,HoldingDays=4,LastExecutionDate=DailyTime(2)};var metrics=PerformanceCalculator.Calculate(100,[new(DailyTime(0),120),new(DailyTime(1),110)],[win,loss],0,252,DailyTime(0,9,0));Check(metrics.Trades==2&&metrics.WinRate==50&&metrics.ProfitFactor==2&&metrics.Expectancy==5&&metrics.AverageHoldingDays==3&&Math.Abs(metrics.MaxDrawdown-100m/12)<.00001m,"central performance hand calculation");Check(PerformanceCalculator.Calculate(100,[],[],0,252).WinRate==null,"empty statistics are unavailable not zero wins");
        using var db=new TradingStore(System.IO.Path.Combine(Dir,"oversold.db"));run=DailyRun(scale);db.State("oversold-config",run.Configuration);db.State("oversold-facts",DailyFacts(8));db.State(run.Id,run);var restored=db.State<OversoldResult>(run.Id)!;Check(restored.Trades[0].Cluster.Signature==run.Trades[0].Cluster.Signature&&restored.Trades[0].Configuration.EntryRatios=="40,30,30"&&restored.ToHistory().Fills.Last().Realized==run.Trades[0].RealizedPnl,"SQLite detailed snapshot and result history restore");
        cfg=DailyConfig();run=DailyRun(scale,cfg,support:new FixedDailySupport(n=>n>=4?120:80));Check(run.Trades[0].Executions.Count(e=>e.Buy)==1,"additional drop alone insufficient without support AND");cfg.RequireSupportForAdditionalEntry=false;Check(DailyRun(scale,cfg,support:new FixedDailySupport(n=>n>=4?120:80)).Trades[0].Executions.Count(e=>e.Buy)==3,"explicit additional support switch respected");
        facts=DailyFacts(8);facts.RiskRecords=[..facts.RiskRecords,new("005930",DailyDates.Of(scale[3]),true,DailyTime(3))];run=DailyRun(scale,facts:facts);Check(!run.Signals.Any(s=>s.Action=="Buy"&&s.SignalTime==DailyTime(3)),"additional entry requires point-in-time risk false");
        PriceBar[] changed=[..scale.Take(5),DailyBar(5,64),DailyBar(6,64)];run=DailyRun(changed,support:new FixedDailySupport(n=>n>=4?75:80));Check(run.Trades[0].Cluster.Lower==70&&run.Trades[0].Executions.Last().SignalTime==DailyTime(5)&&run.Trades[0].ExitReason=="SupportBreak","new lower support after scale does not move initial stop");
        cfg=DailyConfig();cfg.MaxHoldingDays=1;var cooldown=Enumerable.Range(0,12).Select(i=>i<2?DailyBar(i,100):i<4?DailyBar(i,80,high:100):DailyBar(i,75,high:100)).ToArray();run=DailyRun(cooldown,cfg,support:new FixedDailySupport(n=>n>=5?75:80));Check(run.Trades.Count==2&&run.Trades[1].Reentry&&run.Trades[1].FirstExecutionDate==DailyTime(10,9,0),"five completed sessions cooldown plus lower new cluster");
        cfg.AllowEarlyReentryWithNewCluster=true;run=DailyRun(cooldown,cfg,support:new FixedDailySupport(n=>n>=5?75:80));Check(run.Trades[1].FirstExecutionDate==DailyTime(5,9,0),"early reentry requires explicit exception");cfg.AllowEarlyReentryWithNewCluster=false;Check(DailyRun(cooldown,cfg).Trades.Count==1,"same support cannot bypass lower-cluster reentry rule");
        cfg=DailyConfig();cfg.UseTakeProfit1=true;PriceBar[] halted=[..basic.Take(3),DailyBar(3,90,open:80),DailyBar(4,60),DailyBar(5,55)];facts=DailyFacts(6);facts.StatusRecords[4]=facts.StatusRecords[4] with{Suspended=true};run=DailyRun(halted,cfg,facts);Check(run.Trades[0].ExitReason=="SupportBreak"&&run.Trades[0].Executions.Count==2,"stop replaces queued profit order during halt");
        cfg=DailyConfig();cfg.UseTakeProfit1=true;cfg.PlannedInvestment=300;run=DailyRun([..basic.Take(3),DailyBar(3,90,open:80),DailyBar(4,90),DailyBar(5,90)],cfg);Check(run.Trades[0].Executions.Count==1&&run.Notices.Count(n=>n.Contains("TP1 0주"))==1,"rounded zero profit leg completes once without fake fill");
        cfg=DailyConfig();cfg.TouchPolicy=DailyTouchPolicy.CloseOnly;cfg.UseTakeProfit1=true;Check(DailyRun(collision,cfg).Trades[0].Executions.Count==1,"close-only ignores intraday touches");
        facts=DailyFacts(5);run=DailyRun([..basic.Take(3),basic[4]],facts:facts);Check(run.Trades[0].FirstExecutionDate==DailyTime(4,9,0),"missing stock bar delays next available open");Check(DailyRun(basic,start:4).Trades.Count==0,"warmup produces indicators but never past orders");
        for(int cut=3;cut<scale.Length;cut++){var p=DailyRun(scale.Take(cut).ToArray());var full=DailyRun(scale);Check(Serialization.Pack(p.Signals)==Serialization.Pack(full.Signals.Where(s=>s.SignalTime<=DailyTime(cut-1)).ToArray()),"signal prefix invariance length "+cut);}
        Throws<System.Text.Json.JsonException>(()=>Serialization.Unpack<FundamentalRiskRecord>("{\"Symbol\":\"005930\",\"Date\":\"2025-01-01\",\"KnownAt\":\"2025-01-01T08:00:00+09:00\"}"),"omitted risk flag cannot silently mean false");
        facts=DailyFacts(5);facts.StatusRecords=[null!];Throws<InvalidOperationException>(facts.Validate,"null fact row validation");
        facts=DailyFacts(5);facts.TradingValues=facts.TradingValues.Select(v=>v with{KnownAt=DailyTime(50)}).ToArray();Check(DailyRun(basic,facts:facts).Trades.Count==0,"future turnover publication is unavailable in past");
        facts=DailyFacts(5);facts.MarketSessions[2]=facts.MarketSessions[2] with{Close=DailyTime(2,14,0)};Throws<InvalidOperationException>(()=>DailyRun(basic,facts:facts),"bar not yet finalized at declared session close rejected");
        using var cancelled=new CancellationTokenSource();cancelled.Cancel();Throws<OperationCanceledException>(()=>new OversoldBacktest().Run(new(DailyStock,basic,"fixture",DailyTime(100)),DailyConfig(),new(2025,1,3),new(2025,1,5),DailyFacts(5),cancelled.Token),"daily backtest cancellation");
